PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password TEXT NOT NULL,recovery TEXT NOT NULL,created INTEGER NOT NULL,last_seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS servers(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id INTEGER NOT NULL REFERENCES users(id),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL DEFAULT 'member',muted_until INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(server_id,user_id));
CREATE TABLE IF NOT EXISTS bans(server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(server_id,user_id));
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,server_id TEXT REFERENCES servers(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'text',private INTEGER NOT NULL DEFAULT 0,pair_key TEXT UNIQUE,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS channel_members(channel_id TEXT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(channel_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,channel_id TEXT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created INTEGER NOT NULL,edited INTEGER,pinned INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,client_id TEXT NOT NULL,UNIQUE(user_id,client_id));
CREATE INDEX IF NOT EXISTS messages_channel ON messages(channel_id,id);
CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(message_id,user_id));
CREATE TABLE IF NOT EXISTS invites(hash TEXT PRIMARY KEY,server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,created_by INTEGER NOT NULL REFERENCES users(id),expires INTEGER NOT NULL,remaining INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,user_id INTEGER NOT NULL UNIQUE REFERENCES users(id),seen INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS calls_channel ON calls(channel_id,seen);
CREATE TABLE IF NOT EXISTS signals(id INTEGER PRIMARY KEY AUTOINCREMENT,channel_id TEXT NOT NULL,from_call TEXT NOT NULL,to_call TEXT NOT NULL,payload TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS signals_target ON signals(to_call,id);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,hits INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor INTEGER NOT NULL,server_id TEXT NOT NULL,action TEXT NOT NULL,target INTEGER NOT NULL,created INTEGER NOT NULL);
PRAGMA user_version=1;
